const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const r=$input.first().json||{};
const f=r.fields||r;
const clientBase=String(f['Clayroots Base ID']||'').trim();
const raw=String(f['Intent Tables']||'');
const lines=raw.split('\n').map(s=>s.trim()).filter(Boolean);
const tables=[];
for(const ln of lines){
  let t=ln;
  if(ln.includes('/')){ const parts=ln.split('/').map(s=>s.trim()).filter(Boolean); t=parts.find(p=>/^tbl/.test(p))||''; }
  if(/^tbl/.test(t) && clientBase) tables.push({ baseId: clientBase, tableId: t });
}
const clientRecId=r.id||'';
const clientName=f['Client']||'';
if(!tables.length) return [{ json: { clientRecId, clientName, baseId:'', tableId:'' } }];
return tables.map(t=>({ json: { clientRecId, clientName, baseId:t.baseId, tableId:t.tableId } }));

// Prep Rows: one item per row read from the view, carrying its table's plan (the visible
// columns). A table whose view could not be read yields one read-error item with the reason,
// so the run's row says exactly why nothing was enrolled from it.
let tables=[]; try{ tables=$('Plan View').all().map(i=>i.json).filter(t=>t&&t.baseId); }catch(e){}
const rows=$input.all();
const out=[];
const seenTables=new Set();
for(const it of rows){
  const j=it.json||{};
  let src=null;
  try{ const pi=it.pairedItem; const idx=(typeof pi==='number')?pi:(pi&&pi.item); if(idx!==undefined&&idx!==null) src=tables[idx]||null; }catch(e){}
  if(!src && tables.length===1) src=tables[0];
  if(!src) src=tables[0]||{};
  seenTables.add(src.tableId);
  if(src.why){ if(!out.some(o=>o.json._readError&&o.json.tableId===src.tableId)) out.push({ json: { _readError:true, tableId:src.tableId||'', errorMessage:String(src.why).slice(0,160) } }); continue; }
  if(j.error){ out.push({ json: { _readError:true, tableId:src.tableId||'', errorMessage:String((j.error&&(j.error.message||j.error))||'read failed').slice(0,160) } }); continue; }
  if(!j.id) continue;
  out.push({ json: { recordId:j.id, baseId:src.baseId||'', tableId:src.tableId||'', clientRecId:src.clientRecId||'', clientName:src.clientName||'', pvWorkspace:src.pvWorkspace||'', visible:src.visible||null, row:(j.fields||j) } });
}
// A table with a broken view may have produced no row items at all: still report it.
for(const t of tables){ if(t.why&&!seenTables.has(t.tableId)) out.push({ json: { _readError:true, tableId:t.tableId||'', errorMessage:String(t.why).slice(0,160) } }); }
// No ready rows: emit one placeholder so the chain reaches Build Client Log and the run still writes its row.
if(!out.length) return [{ json: { _empty:true } }];
return out;

// Route Rows: one enroll per row of the "LinkedIn" view, on the Deploy View to Campaign doctrine.
//
// The view's visible columns are the contract. Every visible column that is not a machine field,
// a never-block field or an identity field is a variable: sent to Alta as extraInfoData under its
// snake_case name, and REQUIRED, a row missing it is skipped with "missing <column>". Hide a
// column in the view and it is neither sent nor required. Nothing here is a list of what to send.
//
// Identity, hard: LinkedIn URL, first_name, Company (or company_clean). Target: LinkedIn Campaign,
// a pull-in URL. A row already stamped LinkedIn Routed At is skipped: the view shows the whole
// channel, history included; the stamp is what says "done".
const MACHINE=new Set(['Status','MV','MV P0','MV P1','MV P2','MV P3','BB','P1','P2','P3','P1 (Trykitt)','P2 (LeadMagic)','P3 (Prospeo)','Source','Email Source','Contact Source','Contact Key','Run ID','Build Date','Created','Seniority Rank','segment','query_name','ingested_at','RankInCompany','Co Rank','Campaign Segment','reloaded_patch','manually_approved','public_emails_clean','Email','Domain','Campaigns','Campaigns (old text)','Messages Sent','Last Contacted','Campaign Status','Bounce Reason','Synced At','Deploy Error','Name','Valid','Intent Status','LinkedIn Campaign','Email Campaign','LinkedIn Routed At','Email Routed At','Target Campaign','routed_at','Enroll Confirmed','Enroll Error','Event Type','Final Email','company_clean','First Hire']);
// Never-block: sent when filled, never skip a row when empty. The ClayRoots build fields plus the
// intent convention (contact, job, company, signal fields the intent machine writes, see
// n8n/INTENT-PLAYS.md). A visible column OUTSIDE this set is a required variable: empty = row skipped.
const IGNORE=new Set(['last_name','Title','Social','Phone','MX Provider','MX provider','MX','LinkedIn URL','City','State','State Full','Country','Zip','Street',
  'Seniority','Department','Job ID','Job Title','Job Link','Job Posted','Job Description','Job Seniority','Job Function','Job Employment Type','Job Industries','Job Applicants','Job Salary','Job Poster Name','Job Poster Title','Job Poster LinkedIn',
  'Existing In Role','ICP Reason','Description','Industry Groups','Employees','Revenue Range','Score','Keywords','Company Status','Start Date','Company City','Company State','Phones','Public Emails','Social URLs','Redirect Domain','Email Pattern','Signal Detail','detected_at']);
// Any column whose name starts with 'Job ' is convention too (Operator ruling 2026-08-23).
const neverBlock=(col)=>IGNORE.has(col)||/^job\s/i.test(String(col));
const IDENTITY=new Set(['first_name','Company']);
const snake=k=>String(k).replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase();
const val=v=>{ if(v===null||v===undefined) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='number'||typeof v==='boolean') return String(v); if(Array.isArray(v)) return v.filter(x=>typeof x==='string'||typeof x==='number').join(', '); if(typeof v==='object'&&typeof v.value==='string') return v.value.trim(); if(typeof v==='object'&&typeof v.name==='string') return v.name; return ''; };
const out=[];
for(const it of $input.all()){
  const p=it.json||{};
  if(!p.recordId) continue;
  const f=p.row||{};
  const base={ recordId:p.recordId, baseId:p.baseId, tableId:p.tableId, clientRecId:p.clientRecId, clientName:p.clientName, name:val(f['Name'])||val(f['LinkedIn URL']) };
  const fail=(reason)=>out.push({ json: Object.assign({ action:'failed_precheck', reason },base) });
  if(val(f['LinkedIn Routed At'])) continue;                       // already done on this channel
  const url=val(f['LinkedIn Campaign']);
  if(!/^https?:\/\//i.test(url)){ fail('LinkedIn Campaign is not a valid URL'); continue; }
  const linkedinUrl=val(f['LinkedIn URL']);
  if(!/^https?:\/\//i.test(linkedinUrl)){ fail('missing LinkedIn URL'); continue; }
  const fn=val(f['first_name']); if(!fn){ fail('missing first_name'); continue; }
  const comp=val(f['company_clean'])||val(f['Company']); if(!comp){ fail('missing Company'); continue; }
  const otherDone=!val(f['Email Campaign'])||!!val(f['Email Routed At']);
  const extra={}; const missing=[];
  const visible=Array.isArray(p.visible)?p.visible:[];
  for(const col of visible){
    if(MACHINE.has(col)||neverBlock(col)||IDENTITY.has(col)) continue;
    const v=val(f[col]);
    if(v) extra[snake(col)]=v.length>4000?v.slice(0,4000):v; else missing.push(col);
  }
  if(missing.length){ fail('missing '+missing.join(', ').slice(0,140)); continue; }
  // Never-block columns ride along when visible and filled, never skip a row when empty.
  for(const col of visible){ if(!neverBlock(col)||col==='LinkedIn URL'||col==='last_name') continue; const v=val(f[col]); if(v) extra[snake(col)]=v; }
  const dom=val(f['Domain']);
  const body={ firstName:fn, lastName:val(f['last_name']), company:comp, linkedinUrl, extraInfoData:extra };
  if(dom) body.companyWebsite=/^https?:\/\//i.test(dom)?dom:'https://'+dom;
  const email=val(f['Final Email']); if(email) body.email=email;
  out.push({ json: Object.assign({ action:'enroll', otherDone, campaign_url:url, enroll_body:body },base) });
}
if(!out.length) return [{ json: { _empty:true } }];
return out;

const enrolls=$input.all();
let resolved=[]; try{ resolved=$('Route Rows').all().map(i=>i.json).filter(r=>r&&r.action==='enroll'); }catch(e){}
const out=[];
for(let i=0;i<enrolls.length;i++){
  const e=(enrolls[i]&&enrolls[i].json)||{};
  const r=resolved[i]||{};
  if(!r.recordId) continue;
  const ok=!(e&&e.error);
  out.push({ json: {
    recordId:r.recordId, baseId:r.baseId, tableId:r.tableId, clientRecId:r.clientRecId, clientName:r.clientName, name:r.name, otherDone:!!r.otherDone,
    ok: ok,
    reason: ok?'':String((e.error&&(e.error.message||e.error))||'enroll failed after retries').slice(0,160)
  }});
}
return out;

const sd2=$getWorkflowStaticData('global'); const rs=sd2.runStartedAt||0;
let tables=[]; try{ tables=$('Parse Client Config').all().map(i=>i.json).filter(t=>t&&t.baseId); }catch(e){}
const clientRecId=(tables[0]&&tables[0].clientRecId)||'';
const clientName=(tables[0]&&tables[0].clientName)||'';
let prep=[]; try{ prep=$('Prep Rows').all().map(i=>i.json); }catch(e){}
const ready=prep.filter(r=>r&&r.recordId).length;
const readErrors=prep.filter(r=>r&&r._readError).map(r=>({ name:'table '+(r.tableId||'?')+': read failed', reason:r.errorMessage||'' }));
let routes=[]; try{ routes=$('Route Rows').all().map(i=>i.json).filter(r=>r&&r.recordId); }catch(e){}
let results=[]; try{ results=$('Stamp Results').all().map(i=>i.json); }catch(e){}
const ok=results.filter(r=>r.ok);
const failed=results.filter(r=>!r.ok).concat(routes.filter(r=>r.action==='failed_precheck')).concat(readErrors);
const noEmail=routes.filter(r=>r.action==='no_email');
const byTable={};
for(const t of tables){ byTable[t.tableId]={ ready:0, enrolled:0, failed:0, noEmail:0 }; }
for(const r of routes){ const b=byTable[r.tableId]||(byTable[r.tableId]={ready:0,enrolled:0,failed:0,noEmail:0}); b.ready++; if(r.action==='no_email')b.noEmail++; if(r.action==='failed_precheck')b.failed++; }
for(const r of results){ const b=byTable[r.tableId]||(byTable[r.tableId]={ready:0,enrolled:0,failed:0,noEmail:0}); if(r.ok)b.enrolled++; else b.failed++; }
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const parts=['**'+nf(ready)+' ready, '+nf(ok.length)+' enrolled, '+failed.length+' failed**'];
if(!tables.length) parts.push('No usable Intent Tables lines (need tbl ids + Clayroots Base ID on the row); nothing to do.');
const tLines=Object.keys(byTable).map(tid=>{ const b=byTable[tid]; return '- **'+tid+':** '+nf(b.ready)+' ready · '+nf(b.enrolled)+' enrolled · '+nf(b.failed)+' failed · '+nf(b.noEmail)+' no email'; });
if(tLines.length) parts.push('**Tables**\n'+tLines.join('\n'));
if(failed.length) parts.push('**FAILED ('+failed.length+')**\n'+failed.slice(0,5).map(f=>'- '+(f.name||f.recordId||'?')+': '+(f.reason?String(f.reason).slice(0,120):'enroll failed')).join('\n')+(failed.length>5?'\n- ...and '+(failed.length-5)+' more':''));
if(noEmail.length) parts.push('**Skipped ('+noEmail.length+', no email)**\n'+noEmail.map(r=>r.name||r.recordId||'?').join(', '));
const launch=sd2.launch||{};
if(!Array.isArray(sd2.intentResults)) sd2.intentResults=[];
sd2.intentResults.push({client:clientName, ready, enrolled:ok.length, failed:failed.length, target:tables.map(t=>t.tableId).join(', ')});
const row={
 'Automation':'Add Intent Leads to Alta',
 'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
 'Run at': $now.toISO(),
 'Records In': ready,
 'Records Out': ok.length,
 'Errors': failed.length,
 'Target': tables.map(t=>t.tableId).join(', '),
 'Trigger': launch.trigger||'schedule',
 'Execution ID': String($execution.id)+'-'+(clientRecId||'x'),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': parts.join('\n\n')
};
if(clientRecId) row['Client']=[clientRecId];
return [{json:row}];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];

const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.intentResults=[];
// Scheduled runs enroll for every client with Intent Tables. A launched run with a Client on its launch row serves that client only.
const cf=String((sd.launch||{}).clientFilter||'');
const all=$input.all().filter(it=>it.json&&it.json.id);
const picked=cf?all.filter(it=>it.json.id===cf):all;
sd.syncScope=cf?(picked.length?'one client (on demand)':'client filter matched no Intent client'):'all clients';
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the launch-row close.
if(!picked.length) return [{ json: { _empty:true } }];
return picked;

// Closes the Hub launch row of an on-demand run with a roll-up of the per-client rows.
// A scheduled run has no launch row and this leg emits nothing.
const sd=$getWorkflowStaticData('global');
const launch=sd.launch||{};
if(!launch.recordId) return [];
const rs=sd.runStartedAt||launch.startedAt||$now.toMillis();
const results=sd.intentResults||[];
const ready=results.reduce((s,r)=>s+(r.ready||0),0);
const enrolled=results.reduce((s,r)=>s+(r.enrolled||0),0);
const failed=results.reduce((s,r)=>s+(r.failed||0),0);
const lines=results.map(r=>'- **'+(r.client||'?')+':** '+(r.ready||0)+' ready · '+(r.enrolled||0)+' enrolled · '+(r.failed||0)+' failed');
const parts=['**'+results.length+' client(s), '+ready+' ready, '+enrolled+' enrolled, '+failed+' failed**','**Scope:** '+(sd.syncScope||'all clients')];
if(lines.length) parts.push('**Clients** (one detail row per client below this one)\n'+lines.join('\n'));
if(launch.clientFilter && !results.length) parts.push('**Skipped (1, client filter matched no Intent client)**');
const row={
  'Automation': $workflow.name,
  'Status': failed?'Succeeded with errors':'Succeeded',
  'Run at': $now.toISO(),
  'Records In': ready,
  'Records Out': enrolled,
  'Errors': failed,
  'Target': results.map(r=>r.target||'').filter(Boolean).join(', '),
  'Trigger': 'form',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Duration s': Math.round(($now.toMillis()-rs)/1000),
  'Description': parts.join('\n\n')
};
if(launch.clientFilter) row['Client']=[launch.clientFilter];
return [{json:row}];

// Resolve View (runs once per item): from the base schema, find this Intent table's "LinkedIn"
// view and the field list, and build the URL that returns the view's visible fields. No view ->
// viewUrl '' and a reason; the run logs it and enrolls nothing from that table.
const VIEW='LinkedIn';
const cfg=$('Parse Client Config').item.json||{};
const j=$input.item.json||{};
const body=j.body!==undefined?j.body:j;
const tables=Array.isArray(body.tables)?body.tables:[];
const out=Object.assign({},cfg,{ view:VIEW, viewId:'', viewUrl:'', fieldsById:{}, why:'' });
const t=tables.find(x=>x.id===cfg.tableId||x.name===cfg.tableId);
if(!tables.length) out.why='could not read base schema for '+cfg.baseId;
else if(!t) out.why='table '+cfg.tableId+' not found in base '+cfg.baseId;
else {
  for(const f of (t.fields||[])) out.fieldsById[f.id]=f.name;
  const v=(t.views||[]).find(x=>x.name===VIEW);
  if(!v) out.why='view "'+VIEW+'" not found on table '+(t.name||cfg.tableId)+'; create it (filter: LinkedIn Campaign is not empty)';
  else if((v.type||'grid')!=='grid') out.why='view "'+VIEW+'" is type '+v.type+', not grid';
  else { out.viewId=v.id; out.viewUrl='https://api.airtable.com/v0/meta/bases/'+cfg.baseId+'/views/'+v.id+'?include=visibleFieldIds'; }
}
return { json: out };

// Plan View (runs once per item): the view's visible field names, in view order. This list is
// the contract for every row read from it: each visible column that is not a machine, never-block
// or identity field is a variable that must be filled (Deploy View to Campaign doctrine).
const r=$('Resolve View').item.json||{};
const j=$input.item.json||{};
const body=j.body!==undefined?j.body:j;
const out=Object.assign({},r,{ visible:null });
if(r.viewUrl){
  const ids=Array.isArray(body.visibleFieldIds)?body.visibleFieldIds:null;
  if(ids){ out.visible=ids.map(id=>r.fieldsById[id]).filter(Boolean); }
  else out.why='view metadata call failed for "'+r.view+'": '+String((body&&(body.error&&(body.error.message||body.error.type)))||('HTTP '+(j.statusCode||'?'))).slice(0,120);
}
delete out.fieldsById;
return { json: out };
